function solve(customer, plan, daysSincePurchase) {
  // Standard refund window: 30 days after purchase
  // Acme annual-plan exception: 7 days
  // Acme monthly plans: standard 30 days

  if (customer === 'Acme' && plan === 'annual') {
    return daysSincePurchase <= 7;
  }

  // All other cases (Other customer, or Acme monthly) use 30-day window
  return daysSincePurchase <= 30;
}
